<?php

declare(strict_types=1);

namespace App\Entity;

use App\Entity\Enum\Forge;
use App\Repository\CodeRepositoryRepository;
use Doctrine\ORM\Mapping as ORM;

use function Symfony\Component\Clock\now;

/**
 * A repository of a forge linked to a project: its deliveries may reference
 * the issues of that project, and nothing else. Each link carries its own
 * secret, generated by Cairn, which the forge sends with every delivery.
 * The webhook is installed on the forge through its API, or by hand with
 * the URL and the secret the settings page shows. Unlinking deletes the
 * row: it is the current configuration, like a membership; the code
 * references it produced stay, since they keep the repository's path.
 */
#[ORM\Entity(repositoryClass: CodeRepositoryRepository::class)]
#[ORM\Table(name: 'code_repository')]
#[ORM\UniqueConstraint(name: 'uniq_code_repository', columns: ['project_id', 'forge', 'path'])]
class CodeRepository
{
    /** `group/project`, possibly nested, as in the repository's URL. */
    public const string PATH_PATTERN = '~^/?[\w.-]+(/[\w.-]+)+/?$~';

    #[ORM\Id]
    #[ORM\GeneratedValue]
    #[ORM\Column]
    private ?int $id = null;

    #[ORM\ManyToOne]
    #[ORM\JoinColumn(nullable: false)]
    private Project $project;

    #[ORM\Column(length: 10, enumType: Forge::class)]
    private Forge $forge;

    /** The path of the repository on the forge, `group/project`, as in its URL. */
    #[ORM\Column(length: 255)]
    private string $path;

    /** What the forge sends with each delivery (`X-Gitlab-Token`, the HMAC key on GitHub). */
    #[ORM\Column(length: 64)]
    private string $secret;

    /** The id of the webhook on the forge, once installed through its API. */
    #[ORM\Column(length: 40, nullable: true)]
    private ?string $hookId = null;

    #[ORM\Column(nullable: true)]
    private ?\DateTimeImmutable $installedAt = null;

    #[ORM\Column]
    private \DateTimeImmutable $createdAt;

    public function __construct(Project $project, Forge $forge, string $path, #[\SensitiveParameter] string $secret)
    {
        $this->project = $project;
        $this->forge = $forge;
        $this->path = self::normalizePath($path);
        $this->secret = $secret;
        $this->createdAt = now();
    }

    /** Lower case: GitLab resolves paths regardless of case, deliveries must too. */
    public static function normalizePath(string $path): string
    {
        return mb_strtolower(trim($path, " \t\n\r/"));
    }

    public static function newSecret(): string
    {
        return bin2hex(random_bytes(20));
    }

    public function getId(): ?int
    {
        return $this->id;
    }

    public function getProject(): Project
    {
        return $this->project;
    }

    public function getForge(): Forge
    {
        return $this->forge;
    }

    public function getPath(): string
    {
        return $this->path;
    }

    public function getSecret(): string
    {
        return $this->secret;
    }

    /** Whether a delivery carrying this token comes from this link. */
    public function acceptsToken(#[\SensitiveParameter] string $token): bool
    {
        return hash_equals($this->secret, $token);
    }

    public function regenerateSecret(#[\SensitiveParameter] string $secret): void
    {
        $this->secret = $secret;
    }

    public function isInstalled(): bool
    {
        return null !== $this->hookId;
    }

    public function getHookId(): ?string
    {
        return $this->hookId;
    }

    public function markInstalled(string $hookId): void
    {
        $this->hookId = $hookId;
        $this->installedAt = now();
    }

    public function markUninstalled(): void
    {
        $this->hookId = null;
        $this->installedAt = null;
    }

    public function getInstalledAt(): ?\DateTimeImmutable
    {
        return $this->installedAt;
    }
}
